import json, re, os
from collections import defaultdict

data=json.load(open("tests/Arch/Fixtures/target-map.json"))
rows=data["rows"]

def zone_of(fqcn):
    if not isinstance(fqcn, str):
        return "?"
    parts=fqcn.split("\\")
    return parts[1] if parts and parts[0]=="AzGuard" and len(parts)>1 else "?"

P38={"Attributes","Authorization","Catalog","Changes","Concerns","Configuration","Events","Kernel","Panels","Policies","Schema"}
P39={"Diagnostics","Directories","Laravel","Sources","Storage","Testing"}
batch=[]
for r in rows:
    if r.get("phase")!="P3": continue
    cur=r.get("current")
    if not isinstance(cur, str): continue
    z=zone_of(cur)
    if r["action"] in ("move","close+move") and z in P38:
        batch.append(r)
    elif r["action"] in ("move","close+move") and z in P39 and r["owner"]=="core":
        batch.append(r)
    elif r["action"]=="move" and z=="Filament":
        batch.append(r)

fqcn_map={r["current"]: r["target"] for r in batch}
# all known types: current and target of ALL rows, plus files on disk
known=set()
for r in rows:
    if isinstance(r.get("target"), str):
        for t in r["target"].split(" + "):
            known.add(t.strip())
    if isinstance(r.get("current"), str):
        known.add(r["current"])

# parse diff per file into old uses / new uses and other residual lines after cross-hunk use matching
diff=open("/tmp/product.diff",errors="replace").read()
files=re.split(r"(?=^diff --git )", diff, flags=re.M)

use_re=re.compile(r"^use\s+(?:function\s+|const\s+)?([A-Za-z_\\][A-Za-z0-9_\\]*)\s*(?:as\s+([A-Za-z_][A-Za-z0-9_]*))?\s*;")
ns_re=re.compile(r"^namespace\s+([^;]+);")

interesting=[]
use_adds=[]  # (file, line)
use_dels=[]
ns_changes=[]
other=[]

for f in files:
    if not f.startswith("diff --git"): continue
    m=re.search(r"^diff --git a/(.+?) b/(.+)$", f, re.M)
    a,b=m.group(1),m.group(2)
    if not b.endswith(".php"): 
        # record non-php separately later
        continue
    minus=[]
    plus=[]
    for ln in f.splitlines():
        if ln.startswith(("+++","---","@@","diff","index","rename","similarity","new file","deleted file")): 
            continue
        if ln.startswith("+"):
            plus.append(ln[1:])
        elif ln.startswith("-"):
            minus.append(ln[1:])
    # classify
    def kind(line):
        if ns_re.match(line.strip()): return "ns"
        if use_re.match(line.strip()): return "use"
        return "other"
    # match uses across file via fqcn map
    mu=[ln for ln in minus if kind(ln)=="use"]
    pu=[ln for ln in plus if kind(ln)=="use"]
    used=[False]*len(pu)
    def canon_use(line):
        mm=use_re.match(line.strip())
        fqcn, alias=mm.group(1), mm.group(2)
        mapped=fqcn_map.get(fqcn, fqcn)
        return (mapped, alias)
    unmatched_mu=[]
    for ln in mu:
        c=canon_use(ln)
        found=False
        for i,pl in enumerate(pu):
            if not used[i] and canon_use(pl)==c:
                used[i]=True
                found=True
                break
        if not found:
            unmatched_mu.append(ln)
    unmatched_pu=[pl for i,pl in enumerate(pu) if not used[i]]
    # namespace
    mn=[ln for ln in minus if kind(ln)=="ns"]
    pn=[ln for ln in plus if kind(ln)=="ns"]
    # other: try apply map
    fqcn_pairs=sorted(fqcn_map.items(), key=lambda p:-len(p[0]))
    path_pairs=sorted([(r["current_path"], r["target_path"]) for r in batch if r["current_path"]!=r["target_path"]], key=lambda p:-len(p[0]))
    dbl=sorted([(a.replace("\\","\\\\"), b.replace("\\","\\\\")) for a,b in fqcn_pairs], key=lambda p:-len(p[0]))
    def apply_all(s):
        for a,b in fqcn_pairs:
            if a in s: s=s.replace(a,b)
        for a,b in dbl:
            if a in s: s=s.replace(a,b)
        for a,b in path_pairs:
            if a in s: s=s.replace(a,b)
        return s
    mo=[ln for ln in minus if kind(ln)=="other"]
    po=[ln for ln in plus if kind(ln)=="other"]
    usedo=[False]*len(po)
    unmatched_mo=[]
    for ln in mo:
        tr=apply_all(ln)
        found=False
        for i,pl in enumerate(po):
            if not usedo[i] and pl==tr:
                usedo[i]=True
                found=True
                break
        if not found:
            unmatched_mo.append((ln, tr))
    unmatched_po=[pl for i,pl in enumerate(po) if not usedo[i]]
    if unmatched_mu or unmatched_pu or mn or pn or unmatched_mo or unmatched_po:
        interesting.append((b, mn, pn, unmatched_mu, unmatched_pu, unmatched_mo, unmatched_po))

print("php files with non-paired changes", len(interesting))
# summarize categories
ns_only=0
use_only=0
real_other=0
for b,mn,pn,mu,pu,mo,po in interesting:
    if mo or po:
        real_other+=1
    elif mu or pu:
        use_only+=1
    else:
        ns_only+=1
print("ns_only", ns_only, "use_only_or_ns", use_only, "real_other", real_other)

print("\n===== REAL OTHER (not ns/use and not mapped) =====")
for b,mn,pn,mu,pu,mo,po in interesting:
    if not mo and not po: continue
    print("---", b)
    for ln,tr in mo[:15]:
        print("  -", ln[:200])
    for ln in po[:15]:
        print("  +", ln[:200])

print("\n===== USE ADD/DEL counts =====")
add_n=sum(len(pu) for *_,pu,_,_ in [(b,mn,pn,mu,pu,mo,po) for b,mn,pn,mu,pu,mo,po in interesting])
# fix
adds=dels=0
samples=[]
for b,mn,pn,mu,pu,mo,po in interesting:
    adds+=len(pu); dels+=len(mu)
    if pu or mu:
        samples.append((b,mu,pu))
print("unmatched use dels", dels, "adds", adds, "files", len(samples))
open("/tmp/use_changes.txt","w").write("\n".join(
    f"=== {b}\n"+"\n".join(" - "+x for x in mu)+"\n"+"\n".join(" + "+x for x in pu)
    for b,mu,pu in samples
))
print("wrote /tmp/use_changes.txt", os.path.getsize("/tmp/use_changes.txt"))
